import argon2 from 'argon2';

export const PASSWORD_MIN = 10;
export const PASSWORD_MAX = 128;

// OWASP's minimum Argon2id profile (19 MiB, 2 passes, 1 lane). The salt is generated by the library.
const OPTIONS = { type: argon2.argon2id, memoryCost: 19_456, timeCost: 2, parallelism: 1 } as const;

// NFKC so the same visible password typed on different keyboards/devices hashes identically.
const prepare = (password: string) => password.normalize('NFKC');

export const hashPassword = (password: string): Promise<string> =>
  argon2.hash(prepare(password), OPTIONS);

/** False for a wrong password or a malformed stored hash; never throws on bad input. */
export async function verifyPassword(hash: string, password: string): Promise<boolean> {
  try {
    return await argon2.verify(hash, prepare(password));
  } catch {
    return false;
  }
}

let dummyHash: Promise<string> | undefined;

/** Burns the same Argon2 time as a real check so an unknown email is not faster to reject. */
export async function verifyAgainstDummy(password: string): Promise<void> {
  dummyHash ??= hashPassword('noteflow-dummy-password');
  await verifyPassword(await dummyHash, password);
}
